from pathlib import Pathfrom typing import Optional, Dict, Listimport pandas as pdimport loggingfrom swat_toolkit.io.MappingSWATOutput import ReachMapping, HRUMapping, SubbasinMappinglogger = logging.getLogger(__name__)class SWATOutputManager:    """        >>> output = SWATOutputManager("D:/SWAT/project/TxtInOut")        >>> df_reach = output.read_reach()        >>> df_hru = output.read_hru(hru_id=1)    """    def __init__(self, txinout_dir: Path):        """        Initialize output manager        Args:            txinout_dir: Path to TxtInOut directory        """        self.txinout_dir = Path(txinout_dir)        self._cache = {}        if not self.txinout_dir.exists():            raise FileNotFoundError(f"TxtInOut directory not found: {self.txinout_dir}")    # ==================== Main Read Methods ====================    def read_reach(            self,            reach_id: Optional[int] = None,            month: Optional[int] = None,            variables: Optional[List[str]] = None    ) -> pd.DataFrame:        """        Read reach output (output.rch)        Args:            reach_id: Filter by reach ID            month: Filter by month            variables: Select specific variables        Returns:            DataFrame with reach output data        """        df = self._read_cached('reach', 'output.rch', ReachMapping)        # Apply filters        if reach_id is not None:            df = df[df['RCH'] == reach_id]        if month is not None:            df = df[df['MON'] == month]        if variables is not None:            id_cols = ['RCH', 'GIS', 'MON', 'AREAkm2']            df = df[id_cols + variables]        return df.copy()    def read_hru(            self,            hru_id: Optional[int] = None,            subbasin: Optional[int] = None,            month: Optional[int] = None,            variables: Optional[List[str]] = None    ) -> pd.DataFrame:        """        Read HRU output (output.hru)        Args:            hru_id: Filter by HRU ID            subbasin: Filter by subbasin            month: Filter by month            variables: Select specific variables        Returns:            DataFrame with HRU output data        """        df = self._read_cached('hru', 'output.hru', HRUMapping)        # Apply filters        if hru_id is not None:            df = df[df['HRU'] == hru_id]        if subbasin is not None:            df = df[df['SUB'] == subbasin]        if month is not None:            df = df[df['MON'] == month]        if variables is not None:            id_cols = ['LULC', 'HRU', 'GIS', 'SUB', 'MON', 'AREAkm2']            df = df[id_cols + variables]        return df.copy()    def read_subbasin(            self,            subbasin: Optional[int] = None,            month: Optional[int] = None,            variables: Optional[List[str]] = None    ) -> pd.DataFrame:        """        Read subbasin output (output.sub)        Args:            subbasin: Filter by subbasin ID            month: Filter by month            variables: Select specific variables        Returns:            DataFrame with subbasin output data        """        # Note: SubbasinMapping needs to be defined in mappings.py        df = self._read_cached('sub', 'output.sub', SubbasinMapping)        # Apply filters        if subbasin is not None:            df = df[df['SUB'] == subbasin]        if month is not None:            df = df[df['MON'] == month]        if variables is not None:            id_cols = ['SUB', 'GIS', 'MON', 'AREAkm2']            df = df[id_cols + variables]        return df.copy()    # ==================== Aggregation Methods ====================    def get_monthly_flow(self, reach_id: int) -> pd.DataFrame:        """        Get monthly flow for a specific reach        Args:            reach_id: Reach ID        Returns:            DataFrame with monthly flow data        """        df = self.read_reach(reach_id=reach_id,                             variables=['FLOW_OUTcms', 'FLOW_INcms'])        df = df.groupby('MON').mean().reset_index()        return df    def get_annual_summary(            self,            reach_id: Optional[int] = None,            variables: Optional[List[str]] = None    ) -> pd.DataFrame:        """        Get annual summary statistics        Args:            reach_id: Specific reach (None = all reaches)            variables: Variables to summarize        Returns:            Annual summary DataFrame        """        df = self.read_reach(reach_id=reach_id, variables=variables)        # Default variables if not specified        if variables is None:            variables = ['FLOW_OUTcms', 'SED_OUTtons', 'TOT_Nkg', 'TOT_Pkg']        # Calculate annual statistics        summary = df.groupby('RCH')[variables].agg(['mean', 'sum', 'min', 'max'])        return summary    def get_water_balance(self, hru_id: Optional[int] = None) -> pd.DataFrame:        """        Calculate water balance components for HRUs        Args:            hru_id: Specific HRU (None = all HRUs)        Returns:            Water balance DataFrame        """        variables = ['PRECIP', 'ET', 'SURQ_GEN', 'LATQ', 'GW_Q',                     'PERC', 'WYLD', 'SW_INIT', 'SW_END']        df = self.read_hru(hru_id=hru_id, variables=variables)        # Calculate water balance        df['BALANCE'] = (df['PRECIP'] - df['ET'] - df['WYLD'] -                         (df['SW_END'] - df['SW_INIT']))        return df    # ==================== Cache Management ====================    def _read_cached(            self,            cache_key: str,            filename: str,            mapping_class    ) -> pd.DataFrame:        """        Read file with caching        Args:            cache_key: Key for cache dictionary            filename: Output filename            mapping_class: Column mapping class        Returns:            DataFrame        """        if cache_key not in self._cache:            file_path = self.txinout_dir / filename            if not file_path.exists():                raise FileNotFoundError(f"Output file not found: {file_path}")            logger.debug(f"Reading {filename}...")            self._cache[cache_key] = self._read_output_file(file_path, mapping_class)            logger.debug(f"Cached {cache_key}: {len(self._cache[cache_key])} rows")        return self._cache[cache_key]    def _read_output_file(self, file_path: Path, mapping_class) -> pd.DataFrame:        """        Generic SWAT output file reader        Args:            file_path: Path to output file            mapping_class: Mapping class (ReachMapping, HRUMapping, etc.)        Returns:            DataFrame        """        try:            df = pd.read_fwf(                    file_path,                    colspecs=mapping_class.get_colspecs(),                    names=mapping_class.get_column_names(),                    skiprows=9,                    dtype=mapping_class.get_dtypes()            )            return df        except Exception as e:            logger.error(f"Error reading {file_path}: {e}")            raise    def clear_cache(self):        """Clear all cached data"""        self._cache.clear()        logger.debug("Output cache cleared")    def get_cache_info(self) -> Dict:        """Get information about cached data"""        info = {}        for key, df in self._cache.items():            info[key] = {                'rows': len(df),                'columns': len(df.columns),                'memory_mb': df.memory_usage(deep=True).sum() / 1024 ** 2            }        return info    def __repr__(self):        cached = list(self._cache.keys())        return f"SWATOutputManager(cached={cached})"